${pagingTop} SELECT homepage_id, book_idx, subject, regnumber, volume, author, publisher, year, callnumber, place, code, skin, logoimg, viewtype, category, ( SELECT server_file_name FROM ARCHIVE_PAGE z WHERE z.book_idx = a.book_idx AND code = 1 ) AS server_file_name, orig_width, orig_height, resize_width, resize_height, add_date, add_id, mod_date, mod_id, use_yn FROM ARCHIVE_BOOK a WHERE 1=1 AND use_yn = 'Y' AND homepage_id = #{homepage_id}
AND ${search_type} LIKE '%'||#{search_text}||'%'
AND category = #{category}
