UPDATE ARCHIVE_PAGE a SET
	(code, subject) =
	(
		SELECT rn, 'page'||rn
		FROM (
			SELECT page_idx, ROW_NUMBER() OVER (ORDER BY code) AS rn
			FROM ARCHIVE_PAGE
			WHERE book_idx = #{book_idx}
		) z
		WHERE z.page_idx = a.page_idx
	)
WHERE
	book_idx = #{book_idx}

UPDATE ARCHIVE_PAGE a SET
	code = (SELECT code FROM ARCHIVE_PAGE z WHERE z.book_idx = #{book_idx} AND z.code > a.code and rownum = 1)
WHERE
	book_idx = #{book_idx}
AND page_idx = #{page_idx}

UPDATE ARCHIVE_PAGE a SET
	code = (SELECT code FROM ARCHIVE_PAGE WHERE code)
WHERE
	book_idx = #{book_idx}
AND page_idx = #{page_idx}

