SELECT NVL(MAX(code), 0)+1 FROM ARCHIVE_PAGE WHERE use_yn = 'Y' AND book_idx = #{book_idx}

INSERT INTO ARCHIVE_PAGE (
	page_idx, book_idx, subject, code,
	server_file_name, org_file_name,
	add_date, add_id,
	use_yn
) VALUES (
	ARCHIVE_PAGE_SEQ.NEXTVAL, #{book_idx}, 'page'||#{code}, #{code},
	#{server_file_name}, #{org_file_name},
	SYSDATE, #{add_id},
	#{use_yn}
)

